// =============================================================================
// GET /api/manual/download: 사용자 설명서 배포본 (받는 사람 워터마크 포함)
// =============================================================================
// 권한: 로그인 + 조직 멤버. 설명서는 이 앱을 쓰는 사람 모두에게 필요한 문서라
//       직무로 가르지 않는다. 조직 밖(로그인만 한 사람)에는 주지 않는다.
//
// 무엇을 주나: `docs/manual/download-base.html` (자체 완결 HTML, 화면 42장 포함)에
//       받는 사람 정보를 박아서 준다. 파일 하나라 사내망·오프라인에서도 열린다.
//
// ⚠️ 워터마크는 **가벼운 억지력이지 보호 장치가 아니다**(lib/manual/watermark.ts 참조).
//    「누가 받았는가」의 근거는 여기서 남기는 감사 기록(`manual.downloaded`)이다.

import { readFile } from 'node:fs/promises';
import path from 'node:path';

import { NextResponse } from 'next/server';

import { internalError } from '@/lib/api/error-response';
import { logAudit } from '@/lib/audit';
import { getCurrentOrgId } from '@/lib/auth/current-org';
import {
  buildWatermark,
  issuedAtLabel,
  stampForFilename,
} from '@/lib/manual/watermark';
import { checkRateLimit } from '@/lib/rate-limit';
import { createClient, createAdminClient } from '@/lib/supabase/server';

export const dynamic = 'force-dynamic';
export const runtime = 'nodejs';
export const maxDuration = 30;

/** 배포본은 저장소에 함께 둔다: 배포된 앱과 설명서 판이 늘 같아진다.
 *  next.config.ts 의 outputFileTracingIncludes 가 이 파일을 함수 번들에 넣는다. */
const BASE = path.join(process.cwd(), 'docs', 'manual', 'download-base.html');
const PLACEHOLDER = '<!--WATERMARK-->';

/**
 * 🔴 2026-09-01 기본 «꺼짐». 오빠 판단으로 배포를 보류했다.
 *
 * 이유: 설명서는 제품의 핵심 자료다. 파일로 한 번 나가면 회수할 수 없고, 워터마크는
 *   «무심코 넘기는 것» 만 막는다(HTML 이라 받은 사람이 지울 수 있다).
 *
 * 🔑 설정 화면의 카드만 걷는 것으로는 «보류» 가 되지 않는다. 주소를 아는 사람은 그대로
 *    받는다(CLAUDE.md 「문이 하나가 아닐 수 있다」). 그래서 라우트 자체를 닫는다.
 *    있는 것을 숨기지 않으려고 403 이 아니라 **404** 를 준다: 켜기 전에는 없는 길이다.
 *
 * 되살리려면 Vercel 환경변수에 `MANUAL_DOWNLOAD_ENABLED=true` 를 넣는다.
 * 기본값이 «꺼짐» 이라는 것은 `lib/manual/download-contract.test.ts` 가 지킨다.
 */
function enabled(): boolean {
  return process.env.MANUAL_DOWNLOAD_ENABLED === 'true';
}

export async function GET(req: Request) {
  try {
    if (!enabled()) {
      return NextResponse.json({ error: 'NotFound' }, { status: 404 });
    }
    const supabase = await createClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // 3.9MB 를 만들어 내보내는 요청이라 연타를 막는다.
    const ok = await checkRateLimit({
      key: `manual-download:${user.id}`,
      max: 10,
      windowSeconds: 300,
    });
    if (!ok) {
      return NextResponse.json(
        { error: 'TooManyRequests', message: '잠시 후 다시 시도해 주십시오.' },
        { status: 429 },
      );
    }

    const orgId = await getCurrentOrgId(supabase, user.id);
    if (!orgId) {
      return NextResponse.json(
        { error: 'Forbidden', message: '조직에 소속된 계정만 내려받을 수 있습니다.' },
        { status: 403 },
      );
    }

    const admin = createAdminClient();
    const [{ data: profile }, { data: org }] = await Promise.all([
      admin.from('profiles').select('full_name').eq('id', user.id).maybeSingle(),
      admin.from('organizations').select('name').eq('id', orgId).maybeSingle(),
    ]);

    const email = user.email ?? '';
    const who = {
      name: profile?.full_name?.trim() || email.split('@')[0] || '사용자',
      email,
      org: org?.name ?? '',
      issuedAt: issuedAtLabel(new Date()),
    };

    let base: string;
    try {
      base = await readFile(BASE, 'utf-8');
    } catch {
      // 번들에 파일이 안 들어간 경우다. 조용히 빈 파일을 주면 안 된다.
      console.error('[manual/download] 배포본 파일을 못 읽었다:', BASE);
      return NextResponse.json(
        {
          error: 'NotReady',
          message:
            '설명서 배포본이 준비되지 않았습니다. 운영자에게 알려 주십시오.',
        },
        { status: 503 },
      );
    }

    if (!base.includes(PLACEHOLDER)) {
      // 워터마크 없는 사본이 나가는 것을 막는다. 조용히 넘기면 «표시 없는 배포본» 이 돈다.
      console.error('[manual/download] 워터마크 자리표시자 없음');
      return NextResponse.json(
        { error: 'NotReady', message: '설명서 배포본이 손상되었습니다.' },
        { status: 503 },
      );
    }

    const html = base.replace(PLACEHOLDER, buildWatermark(who));

    await logAudit({
      orgId,
      actorId: user.id,
      actorEmail: user.email,
      action: 'manual.downloaded',
      entityType: 'manual',
      entityId: 'user-manual-v2',
      summary: `사용자 설명서 내려받음: ${who.name}`,
      details: { issued_at: who.issuedAt, bytes: html.length },
      req,
    });

    const filename = `Q-Atelier-사용자설명서-${stampForFilename(new Date())}.html`;
    const ascii = `Q-Atelier-user-manual-${stampForFilename(new Date())}.html`;

    return new NextResponse(html, {
      status: 200,
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Content-Disposition':
          `attachment; filename="${ascii}"; ` +
          `filename*=UTF-8''${encodeURIComponent(filename)}`,
        'Cache-Control': 'no-store',
      },
    });
  } catch (e) {
    return internalError(e, 'manual/download');
  }
}

